def merge_intervals(intervals):
    if not intervals:
        return []
    iv = sorted((start, end) for start, end in intervals)
    merged = []
    cs, ce = iv[0]
    for s, e in iv[1:]:
        if s <= ce:
            if e > ce:
                ce = e
        else:
            merged.append([cs, ce])
            cs, ce = s, e
    merged.append([cs, ce])
    return merged

from heapq import heapify, heappop, heappush

def toposort(nodes, edges):
    indegree = {n: 0 for n in nodes}
    adj = {n: [] for n in nodes}

    for u, v in set(edges):
        adj[u].append(v)
        indegree[v] += 1

    heap = [n for n in nodes if indegree[n] == 0]
    heapify(heap)
    result = []

    while heap:
        u = heappop(heap)
        result.append(u)
        for v in adj[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                heappush(heap, v)

    if len(result) != len(nodes):
        raise ValueError("cycle detected")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError("limit must be positive")
    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError("invalid weight")
    batches = []
    current = []
    current_weight = 0
    for name, weight in items:
        if current and current_weight + weight > limit:
            batches.append(current)
            current = [name]
            current_weight = weight
        else:
            current.append(name)
            current_weight += weight
    if current:
        batches.append(current)
    return batches

import re

_KEY_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")

def parse_env(text):
    env = {}
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        if "=" not in line:
            raise ValueError(f"missing '=' in line: {line!r}")
        key_part, value_part = line.split("=", 1)
        key = key_part.strip()
        value = value_part.strip()
        if not _KEY_RE.fullmatch(key):
            raise ValueError(f"invalid key: {key!r}")
        if len(value) >= 2 and value[0] == value[-1] and value[0] in ("'", '"'):
            value = value[1:-1]
        env[key] = value
    return env

def parse_sse(chunks):
    text = b''.join(chunks).decode('utf-8').replace('\r\n', '\n')
    lines = text.split('\n')
    if text.endswith('\n'):
        lines.pop()
    events = []
    data_lines = []
    for line in lines:
        if line == '':
            if data_lines:
                payload = '\n'.join(data_lines)
                if payload == '[DONE]':
                    break
                events.append(payload)
            data_lines = []
            continue
        if line.startswith(':'):
            continue
        if ':' in line:
            field, value = line.split(':', 1)
            if value.startswith(' '):
                value = value[1:]
        else:
            field, value = line, ''
        if field == 'data':
            data_lines.append(value)
    return events

import math

def retry_delay(attempt, base, cap):
    if attempt < 0:
        raise ValueError("attempt must be nonnegative")
    if base < 0 or cap < 0:
        raise ValueError("base and cap must be nonnegative")
    if not math.isfinite(base) or not math.isfinite(cap):
        raise ValueError("base and cap must be finite")
    if cap == 0 or base == 0:
        return 0.0
    if base >= cap:
        return float(cap)
    threshold = math.log2(cap) - math.log2(base)
    if attempt >= threshold:
        return float(cap)
    return math.ldexp(base, attempt)
